#include <vector>

class Solution {
public:
    int unhappyFriends(int n, std::vector<std::vector<int>>& preferences, std::vector<std::vector<int>>& pairs) {
        std::vector<std::vector<int>> rank(n, std::vector<int>(n, 0));
        for (int i = 0; i < n; ++i) {
            for (int r = 0; r < (int)preferences[i].size(); ++r) {
                rank[i][preferences[i][r]] = r;
            }
        }
        std::vector<int> pairOf(n);
        for (const auto& p : pairs) {
            pairOf[p[0]] = p[1];
            pairOf[p[1]] = p[0];
        }
        int unhappy = 0;
        for (int x = 0; x < n; ++x) {
            int y = pairOf[x];
            for (int u : preferences[x]) {
                if (u == y) break;
                int v = pairOf[u];
                if (rank[u][x] < rank[u][v]) {
                    unhappy++;
                    break;
                }
            }
        }
        return unhappy;
    }
};

