var unhappyFriends = function(n, preferences, pairs) {
    const rank = Array.from({ length: n }, () => new Int32Array(n));
    for (let i = 0; i < n; i++) {
        for (let r = 0; r < preferences[i].length; r++) {
            rank[i][preferences[i][r]] = r;
        }
    }
    const pairOf = new Int32Array(n);
    for (const [x, y] of pairs) {
        pairOf[x] = y;
        pairOf[y] = x;
    }
    let unhappy = 0;
    for (let x = 0; x < n; x++) {
        const y = pairOf[x];
        for (const u of preferences[x]) {
            if (u === y) break;
            const v = pairOf[u];
            if (rank[u][x] < rank[u][v]) {
                unhappy++;
                break;
            }
        }
    }
    return unhappy;
};
